/* From Uiverse.io by Lucaasbre  - Tags: simple, red, minimalist, black, input, dark, login , input effect  */
.__UIV_SCOPE__ .input-group {
  display: flex;
  gap: 10px;
  position: relative;
  padding: 7px 0 0;
  width: 80%;
  margin-bottom: 10px;
  margin-top: 2px;
}

.__UIV_SCOPE__ .input-text {
  font-family: inherit;
  width: 100%;
  border: none;
  border-bottom: 2px solid #7f7f7f;
  border-radius: 0 !important;
  outline: 0;
  font-size: 17px;
  color: #7f7f7f;
  padding: 7px 0;
  background: transparent;
  transition: border-color 0.2s;
}

.__UIV_SCOPE__ .input-text::placeholder {
  color: transparent;
}

.__UIV_SCOPE__ .input-text:placeholder-shown ~ .input-text-label {
  font-size: 17px;
  cursor: text;
}

.__UIV_SCOPE__ .input-text-label {
  position: absolute;
  display: block;
  transition: 0.2s;
  font-size: 17px;
  color: #7f7f7f;
  pointer-events: none;
}

.__UIV_SCOPE__ .input-text:focus {
  padding-bottom: 6px;
  border-width: 3px;
  border-image: linear-gradient(to right, #dd0033, #9f1026);
  border-image-slice: 1;
}

.__UIV_SCOPE__ .input-text:focus ~ .input-text-label {
  color: #dd0033;
}

.__UIV_SCOPE__ .input-text:not(:placeholder-shown) ~ .input-text-label,
.__UIV_SCOPE__ .input-text:focus ~ .input-text-label {
  position: absolute;
  display: block;
  transition: 0.2s;
  font-size: 15px;
  font-weight: 700;
  top: -17px;
}

.__UIV_SCOPE__ .input-text:required,
.__UIV_SCOPE__ .input-text:invalid {
  box-shadow: none;
}
